SET FOREIGN_KEY_CHECKS = 1;

-- Feature window only: excludes each student's outcome academic year, so
-- training features cannot leak the labelled outcome.
CREATE OR REPLACE VIEW ml_feature_set AS
SELECT s.student_id,
       s.current_year,
       COUNT(r.result_id)                                          AS modules_attempted,
       SUM(r.result = 'Pass')                                       AS modules_passed,
       SUM(r.result = 'Fail')                                       AS modules_failed,
       ROUND(AVG(r.final_mark), 2)                                  AS avg_final_mark,
       ROUND(MIN(r.final_mark), 2)                                  AS min_final_mark,
       ROUND(AVG(r.continuous_assessment), 2)                       AS avg_ca_mark,
       ROUND(AVG(r.examination_mark), 2)                            AS avg_exam_mark,
       ROUND(AVG(a.attendance_percentage), 2)                       AS avg_attendance,
       SUM(CASE WHEN r.result = 'Pass' THEN m.credits ELSE 0 END)    AS credits_earned,
       l.risk_level                                                 AS target_risk_level
FROM students s
JOIN student_risk_labels l         ON l.student_id = s.student_id AND l.ml_eligible = 1
JOIN student_module_results r      ON r.student_id = s.student_id
                                  AND CAST(SUBSTRING_INDEX(r.academic_year, '/', 1) AS UNSIGNED)
                                      < CAST(SUBSTRING_INDEX(l.outcome_academic_year, '/', 1) AS UNSIGNED)
JOIN modules m                     ON m.module_id = r.module_id
LEFT JOIN attendance a             ON a.result_id = r.result_id
GROUP BY s.student_id, s.current_year, l.risk_level;
